# Trilingual (pt-BR / en / es) content rendered by git_tips(). See
# tips_render.R for the structure of a "content" object and the L()/step()
# helpers. Non-ASCII characters are written as \u escapes.

.git_tips_content <- function() {
  ui <- list(
    title = L("Guia r\u00e1pido de Git / SSH", "Git / SSH cheat sheet", "Gu\u00eda r\u00e1pida de Git / SSH"),
    subtitle = L(
      "Gerado por git_tips() em %s. Fluxos de trabalho primeiro, refer\u00eancia completa das fun\u00e7\u00f5es abaixo.",
      "Generated by git_tips() on %s. Workflows first, full function reference below.",
      "Generado por git_tips() el %s. Primero los flujos de trabajo, abajo la referencia completa de funciones."
    ),
    workflows = L("Fluxos de trabalho", "Workflows", "Flujos de trabajo"),
    reference = L("Refer\u00eancia de fun\u00e7\u00f5es", "Function reference", "Referencia de funciones"),
    footer = L(
      "Execute git_tips() novamente a qualquer momento para regerar esta p\u00e1gina. Use lang = \"en\" ou \"es\" para trocar o idioma inicial.",
      "Run git_tips() again any time to regenerate this page. Use lang = \"pt-BR\" or \"es\" to change the initial language.",
      "Ejecute git_tips() de nuevo en cualquier momento para regenerar esta p\u00e1gina. Use lang = \"pt-BR\" o \"en\" para cambiar el idioma inicial."
    ),
    console_hint = L(
      "Dica: git_tips(lang = \"en\") ou lang = \"es\" mostra este guia em ingl\u00eas ou espanhol; sem console = TRUE abre uma p\u00e1gina HTML com bot\u00f5es de idioma.",
      "Tip: git_tips(lang = \"pt-BR\") or lang = \"es\" shows this guide in Portuguese or Spanish; without console = TRUE it opens an HTML page with language buttons.",
      "Consejo: git_tips(lang = \"pt-BR\") o lang = \"en\" muestra esta gu\u00eda en portugu\u00e9s o ingl\u00e9s; sin console = TRUE abre una p\u00e1gina HTML con botones de idioma."
    )
  )

  workflows <- list(
    list(
      title = L("Primeira configura\u00e7\u00e3o de SSH em uma m\u00e1quina nova",
                "First-time SSH setup on a new machine",
                "Primera configuraci\u00f3n de SSH en una m\u00e1quina nueva"),
      note = L("Fa\u00e7a isto uma vez por m\u00e1quina, principalmente se Documentos/perfil do usu\u00e1rio for redirecionado pelo OneDrive ou outra ferramenta de sincroniza\u00e7\u00e3o.",
               "Do this once per machine, especially if Documents/user profile is redirected by OneDrive or another cloud-sync tool.",
               "Haga esto una vez por m\u00e1quina, sobre todo si Documentos/perfil de usuario est\u00e1 redirigido por OneDrive u otra herramienta de sincronizaci\u00f3n."),
      steps = list(
        step("get_ssh_home()", L("confirma onde as chaves/config SSH precisam ficar", "confirm where SSH keys/config actually need to live", "confirma d\u00f3nde deben estar las claves/config SSH")),
        step("git_setup_ssh_config(c(work = \"you@work.com\", personal = \"you@personal.com\"), default_account = \"personal\")",
             L("default_account faz git@github.com: (repos de terceiros) usar a chave 'personal'", "default_account lets plain git@github.com: URLs (third-party repos) use the 'personal' key", "default_account hace que git@github.com: (repos de terceros) use la clave 'personal'")),
        step("check_ssh_setup()", L("verifica tudo; rode de novo ap\u00f3s corrigir qualquer aviso", "verify everything lines up; re-run after fixing any warning", "verifica todo; vuelva a ejecutar tras corregir cualquier aviso"))
      )
    ),
    list(
      title = L("Clonar um reposit\u00f3rio de terceiros / p\u00fablico",
                "Cloning someone else's / a public repository",
                "Clonar un repositorio de terceros / p\u00fablico"),
      note = L("N\u00e3o precisa de chave nem de conta: o modo \"auto\" usa HTTPS sempre que o dono do reposit\u00f3rio n\u00e3o tem um alias SSH nesta m\u00e1quina.",
               "No key or account needed: the \"auto\" mode uses HTTPS whenever the repository owner has no SSH alias on this machine.",
               "No se necesita clave ni cuenta: el modo \"auto\" usa HTTPS siempre que el due\u00f1o del repositorio no tenga un alias SSH en esta m\u00e1quina."),
      steps = list(
        step("git_clone(\"tidyverse/dplyr\")", L("slug 'dono/repo'", "'owner/repo' slug", "slug 'due\u00f1o/repo'")),
        step("git_clone(\"https://github.com/tidyverse/dplyr\", depth = 1)", L("URL HTTPS, clone raso", "HTTPS URL, shallow clone", "URL HTTPS, clon superficial"))
      )
    ),
    list(
      title = L("Clonar um reposit\u00f3rio seu (privado, multi-conta)",
                "Cloning one of your own repositories (private, multi-account)",
                "Clonar un repositorio propio (privado, multi-cuenta)"),
      note = L("Se o dono tem alias (Host github.com-<dono>), o SSH por esse alias \u00e9 escolhido sozinho. Para outra conta, passe ssh_alias.",
               "If the owner has an alias (Host github.com-<owner>), SSH through that alias is chosen automatically. For another account, pass ssh_alias.",
               "Si el due\u00f1o tiene alias (Host github.com-<due\u00f1o>), se elige SSH por ese alias autom\u00e1ticamente. Para otra cuenta, pase ssh_alias."),
      steps = list(
        step("git_list_ssh_hosts()", L("veja quais aliases existem", "see which Host aliases are available", "vea qu\u00e9 alias existen")),
        step("git_clone(\"my-account/private-repo\")", L("alias detectado pelo dono", "alias detected from the owner", "alias detectado por el due\u00f1o")),
        step("git_clone(\"my-org/private-repo\", ssh_alias = \"github.com-work\")", L("conta expl\u00edcita", "explicit account", "cuenta expl\u00edcita")),
        step("git_clone(\"owner/repo\", protocol = \"ssh\")", L("for\u00e7a SSH (ou protocol = \"https\")", "force SSH (or protocol = \"https\")", "fuerza SSH (o protocol = \"https\")"))
      )
    ),
    list(
      title = L("Criar um projeto novo (multi-conta)", "Creating a brand new project (multi-account)", "Crear un proyecto nuevo (multi-cuenta)"),
      note = L("Evite usethis::use_github() aqui: ele usa HTTPS por padr\u00e3o e ignora seu alias SSH; com duas ou mais contas \u00e9 f\u00e1cil criar o reposit\u00f3rio na conta errada sem perceber.",
               "Avoid usethis::use_github() here: it defaults to HTTPS and ignores your SSH alias, so with two+ accounts it's easy to create the repo under the wrong one without noticing.",
               "Evite usethis::use_github() aqu\u00ed: usa HTTPS por defecto e ignora su alias SSH; con dos o m\u00e1s cuentas es f\u00e1cil crear el repo en la cuenta equivocada sin notarlo."),
      steps = list(
        step("usethis::create_project(\"path/to/NewProject\", open = FALSE)", L("ou File > New Project, sem use_github()", "or File > New Project, no use_github()", "o File > New Project, sin use_github()")),
        step("usethis::use_git_config(scope = \"project\", user.name = \"<account>\", user.email = \"<account>@example.com\")"),
        step("# ...", L("fa\u00e7a o primeiro commit", "make the first commit", "haga el primer commit")),
        step("git_new_project(\"work\", \"NewProject\")", L("confere identidade gh + ssh, cria o repo, define o remote e faz push", "checks gh + ssh identity match, creates repo, sets remote, pushes", "verifica identidad gh + ssh, crea el repo, define el remote y hace push"))
      )
    ),
    list(
      title = L("Push falha com \"repository not found\", ou um reposit\u00f3rio que voc\u00ea sabe que existe n\u00e3o \u00e9 alcan\u00e7ado",
                "Push fails with \"repository not found\", or a repo you know exists can't be reached",
                "El push falla con \"repository not found\", o un repo que sabe que existe no se alcanza"),
      note = L("Causa mais comum: o remote local ainda \u00e9 HTTPS (ou a URL de push foi definida \u00e0 parte e nunca atualizada).",
               "The most common cause: the local remote is still HTTPS (or its push URL was set separately and never updated).",
               "Causa m\u00e1s com\u00fan: el remote local sigue siendo HTTPS (o su URL de push se defini\u00f3 aparte y nunca se actualiz\u00f3)."),
      steps = list(
        step("git_status_check()", L("mostra URLs de fetch/push e avisa se houver HTTPS", "reports fetch/push URLs and warns if HTTPS is in use", "muestra URLs de fetch/push y avisa si hay HTTPS")),
        step("git_convert_to_ssh()", L("ou git_set_ssh_account(alias, projeto, dono) para uma conta espec\u00edfica", "or git_set_ssh_account(alias, project, owner) for a specific account", "o git_set_ssh_account(alias, proyecto, due\u00f1o) para una cuenta espec\u00edfica")),
        step("git_push_with_local_id()", L("tamb\u00e9m faz essa checagem sozinho (auto_ssh = TRUE)", "also runs this check itself by default (auto_ssh = TRUE)", "tambi\u00e9n hace esta comprobaci\u00f3n solo (auto_ssh = TRUE)"))
      )
    ),
    list(
      title = L("Rotina di\u00e1ria", "Normal daily loop", "Rutina diaria"),
      note = L("As variantes _with_local_id() sempre usam o config SSH f\u00edsico desta m\u00e1quina, nunca um core.sshCommand possivelmente compartilhado entre m\u00e1quinas. Remotes de terceiros (sem alias aqui) ficam em HTTPS, ent\u00e3o pull de repo p\u00fablico alheio continua funcionando.",
               "The _with_local_id() variants always use this machine's own physical SSH config, never a possibly cross-machine-shared core.sshCommand. Third-party remotes (no alias here) stay on HTTPS, so pulling someone else's public repo keeps working.",
               "Las variantes _with_local_id() siempre usan el config SSH f\u00edsico de esta m\u00e1quina, nunca un core.sshCommand posiblemente compartido entre m\u00e1quinas. Los remotes de terceros (sin alias aqu\u00ed) quedan en HTTPS, as\u00ed que el pull de un repo p\u00fablico ajeno sigue funcionando."),
      steps = list(
        step("git_pull_with_local_id()"),
        step("# ...", L("edite arquivos, gert::git_add(), gert::git_commit()", "edit files, gert::git_add(), gert::git_commit()", "edite archivos, gert::git_add(), gert::git_commit()")),
        step("git_push_with_local_id()")
      )
    ),
    list(
      title = L("Preciso guardar o trabalho temporariamente", "Need to put work aside temporarily", "Necesito guardar el trabajo temporalmente"),
      note = L("N\u00e3o precisa abrir um shell para git stash: estas fun\u00e7\u00f5es o encapsulam.",
               "No need to drop into a shell for git stash -- these wrap it directly.",
               "No hace falta abrir una shell para git stash: estas funciones lo envuelven."),
      steps = list(
        step("git_stash_save(\"wip: what's unfinished\")"),
        step("# ...", L("troque de branch, fa\u00e7a pull etc.", "switch branches, pull, etc.", "cambie de rama, haga pull, etc.")),
        step("git_stash_list()"),
        step("git_stash_pop()")
      )
    ),
    list(
      title = L("C\u00f3pia local quebrada/divergente: o remoto \u00e9 a fonte da verdade",
                "Local copy is broken/diverged -- remote is the source of truth",
                "Copia local rota/divergente: el remoto es la fuente de verdad"),
      note = L("Destrutivo: descarta hist\u00f3rico/altera\u00e7\u00f5es locais. Um backup em stash \u00e9 criado automaticamente, a menos que stash_backup = FALSE.",
               "Destructive: discards local history/changes. A stash backup is created automatically unless stash_backup = FALSE.",
               "Destructivo: descarta historial/cambios locales. Se crea un respaldo en stash autom\u00e1ticamente salvo que stash_backup = FALSE."),
      steps = list(
        step("git_pull_force_remote()", L("pede confirma\u00e7\u00e3o e faz stash antes", "prompts for confirmation, stashes local changes first", "pide confirmaci\u00f3n y hace stash antes")),
        step("git_stash_list()", L("s\u00f3 se quiser recuperar o stash depois", "only needed if you want to recover the stash afterwards", "solo si quiere recuperar el stash despu\u00e9s")),
        step("git_stash_pop()")
      )
    ),
    list(
      title = L("O hist\u00f3rico remoto precisa ser sobrescrito pelo local (ap\u00f3s rebase/amend)",
                "Remote history needs to be overwritten with local (after rebase/amend)",
                "El historial remoto debe sobrescribirse con el local (tras rebase/amend)"),
      note = L("Mais arriscado que o fluxo anterior: reescreve hist\u00f3rico que outras m\u00e1quinas/pessoas podem ter baixado. Inclui checagem de diverg\u00eancia e tag de backup.",
               "Riskier than the previous workflow: rewrites history other machines/people may have fetched. Includes its own divergence check and backup tag.",
               "M\u00e1s arriesgado que el flujo anterior: reescribe historial que otras m\u00e1quinas/personas pueden haber descargado. Incluye verificaci\u00f3n de divergencia y etiqueta de respaldo."),
      steps = list(
        step("git_push_force_remote()", L("faz fetch, detecta commits s\u00f3 no remoto, marca o estado antigo com tag e ent\u00e3o force-push", "fetches, checks for remote-only commits, tags the old remote state, then force-pushes", "hace fetch, detecta commits solo remotos, etiqueta el estado antiguo y luego force-push"))
      )
    ),
    list(
      title = L("Algo relacionado \u00e0 autentica\u00e7\u00e3o parece errado", "Something authentication-related looks wrong", "Algo relacionado con la autenticaci\u00f3n parece mal"),
      note = L("Rode de cima para baixo; cada uma restringe uma camada diferente do problema.",
               "Run these top to bottom; each narrows down a different layer of the problem.",
               "Ejecute de arriba hacia abajo; cada una acota una capa distinta del problema."),
      steps = list(
        step("check_ssh_setup()", L("'~' vs. home f\u00edsico, core.sshCommand, chaves, conflitos de nuvem", "'~' vs physical home, core.sshCommand, key files, cloud-sync conflicts", "'~' vs. home f\u00edsico, core.sshCommand, claves, conflictos de nube")),
        step("git_test_ssh_alias(\"work\")", L("com qual conta o alias realmente autentica?", "which account does this alias really authenticate as?", "\u00bfcon qu\u00e9 cuenta autentica realmente este alias?")),
        step("git_status_check()", L("o remote deste repo usa SSH ou HTTPS?", "is this specific repo's remote using SSH or HTTPS?", "\u00bfel remote de este repo usa SSH o HTTPS?")),
        step("git_list_ssh_hosts()", L("quais aliases existem de fato no config SSH", "which aliases actually exist in the SSH config", "qu\u00e9 alias existen realmente en el config SSH"))
      )
    )
  )

  reference <- list(
    list(
      group = L("Configura\u00e7\u00e3o e diagn\u00f3stico", "Setup & diagnostics", "Configuraci\u00f3n y diagn\u00f3stico"),
      items = list(
        list(fn = "get_os_type()", desc = L("Detecta windows / macos / linux / unix.", "Detects windows / macos / linux / unix.", "Detecta windows / macos / linux / unix.")),
        list(fn = "get_ssh_home()", desc = L("Resolve o diret\u00f3rio home f\u00edsico real desta m\u00e1quina, contornando o redirecionamento de perfil do OneDrive/Google Drive.", "Resolves this machine's true physical home directory, routing around OneDrive/Google Drive profile redirection.", "Resuelve el directorio home f\u00edsico real de esta m\u00e1quina, evitando la redirecci\u00f3n de perfil de OneDrive/Google Drive.")),
        list(fn = "check_cloud_sync_conflicts(path)", desc = L("Avisa se um caminho est\u00e1 dentro de uma pasta de sincroniza\u00e7\u00e3o (OneDrive, Google Drive, iCloud, Dropbox, Box).", "Warns if a path sits inside a cloud-sync folder (OneDrive, Google Drive, iCloud, Dropbox, Box).", "Avisa si una ruta est\u00e1 dentro de una carpeta de sincronizaci\u00f3n (OneDrive, Google Drive, iCloud, Dropbox, Box).")),
        list(fn = "git_setup_ssh_config(accounts, bind_global, default_account)", desc = L("Escreve um config SSH multi-conta (aliases Host) no .ssh f\u00edsico e liga o core.sshCommand. default_account d\u00e1 uma chave padr\u00e3o ao host github.com puro.", "Writes a multi-account SSH config (Host aliases) into the physical .ssh directory and binds core.sshCommand. default_account gives the bare github.com host a default key.", "Escribe un config SSH multi-cuenta (alias Host) en el .ssh f\u00edsico y enlaza core.sshCommand. default_account da una clave por defecto al host github.com simple.")),
        list(fn = "check_ssh_setup()", desc = L("Diagn\u00f3stico completo: compara '~' com o home f\u00edsico, verifica core.sshCommand e lista as chaves encontradas.", "Full diagnostic: compares R's '~' to the physical home, verifies core.sshCommand, lists keys found.", "Diagn\u00f3stico completo: compara '~' con el home f\u00edsico, verifica core.sshCommand y lista las claves encontradas.")),
        list(fn = "git_list_ssh_hosts()", desc = L("Lista os aliases Host definidos no config SSH f\u00edsico.", "Lists the Host aliases currently defined in the physical SSH config.", "Lista los alias Host definidos en el config SSH f\u00edsico.")),
        list(fn = "git_test_ssh_alias(alias, host)", desc = L("Roda 'ssh -T' num alias e l\u00ea a sauda\u00e7\u00e3o do GitHub para confirmar com qual conta ele autentica.", "Runs 'ssh -T' against a Host alias and parses GitHub's greeting to confirm which account it authenticates as.", "Ejecuta 'ssh -T' en un alias y lee el saludo de GitHub para confirmar con qu\u00e9 cuenta autentica.")),
        list(fn = "git_ssh_env() / git_system2()", desc = L("Blocos de baixo n\u00edvel: GIT_SSH_COMMAND por chamada, usado internamente por todas as fun\u00e7\u00f5es de rede.", "Low-level building blocks: per-call GIT_SSH_COMMAND override used internally by every network-facing helper.", "Bloques de bajo nivel: GIT_SSH_COMMAND por llamada, usado internamente por todas las funciones de red."))
      )
    ),
    list(
      group = L("Protocolo do remote (HTTPS vs SSH)", "Remote protocol (HTTPS vs SSH)", "Protocolo del remote (HTTPS vs SSH)"),
      items = list(
        list(fn = "git_remote_urls(remote)", desc = L("Mostra as URLs de fetch E push separadamente: um remote pode ter push URL divergente.", "Reports a remote's fetch AND push URLs separately -- a remote can have a push URL that silently diverges.", "Muestra las URLs de fetch Y push por separado: un remote puede tener una URL de push divergente.")),
        list(fn = "git_status_check(remote)", desc = L("Imprime as URLs do remote e avisa se houver HTTPS.", "Prints a remote's URLs and warns if HTTPS is in use anywhere.", "Imprime las URLs del remote y avisa si hay HTTPS.")),
        list(fn = "git_convert_to_ssh(remote, ssh_alias)", desc = L("Reescreve um remote HTTPS para SSH (fetch e/ou push), escolhendo o alias pelo dono do repo.", "Rewrites an HTTPS remote (fetch and/or push URL) to SSH, picking the alias from the repo owner.", "Reescribe un remote HTTPS a SSH (fetch y/o push), eligiendo el alias por el due\u00f1o del repo.")),
        list(fn = "git_set_ssh_account(account_name, project_name, owner, host)", desc = L("Aponta o remote do repo local para um alias Host espec\u00edfico.", "Points the local repo's remote at a specific Host alias.", "Apunta el remote del repo local a un alias Host espec\u00edfico."))
      )
    ),
    list(
      group = L("Criar projeto novo", "Creating a new project", "Crear un proyecto nuevo"),
      items = list(
        list(fn = "git_new_project(account_alias, repo_name, owner, private, push, branch)", desc = L("Com travas: confere que a identidade do gh E o alias SSH batem com 'owner' antes de criar o repo, definir origin e dar push.", "Guard-railed: verifies gh's identity AND the SSH alias both match 'owner' before creating the repo, setting origin, and pushing.", "Con salvaguardas: verifica que la identidad de gh Y el alias SSH coincidan con 'owner' antes de crear el repo, definir origin y hacer push."))
      )
    ),
    list(
      group = L("Clonagem", "Cloning", "Clonaci\u00f3n"),
      items = list(
        list(fn = "git_clone(repo, ssh_alias, protocol, ...)", desc = L("Clona qualquer reposit\u00f3rio. protocol = \"auto\": HTTPS para p\u00fablico/terceiros, SSH por alias para os seus. Aceita slug, URL HTTPS ou SSH.", "Clones any repository. protocol = \"auto\": HTTPS for public/third-party, SSH through an alias for your own. Accepts slug, HTTPS or SSH URL.", "Clona cualquier repositorio. protocol = \"auto\": HTTPS para p\u00fablicos/terceros, SSH por alias para los propios. Acepta slug, URL HTTPS o SSH.")),
        list(fn = "git_build_ssh_url(repo, host, ssh_alias)", desc = L("Monta a URL SSH usada por git_clone() e git_convert_to_ssh().", "Builds the SSH remote URL string used by git_clone() and git_convert_to_ssh().", "Construye la URL SSH usada por git_clone() y git_convert_to_ssh().")),
        list(fn = "git_build_https_url(repo, host)", desc = L("Monta a URL HTTPS equivalente (sem chave).", "Builds the equivalent HTTPS URL (no key needed).", "Construye la URL HTTPS equivalente (sin clave)."))
      )
    ),
    list(
      group = L("Pull / push di\u00e1rios", "Daily pull / push", "Pull / push diarios"),
      items = list(
        list(fn = "git_pull_with_local_id(branch, auto_ssh)", desc = L("Pull com o config SSH f\u00edsico desta m\u00e1quina; converte HTTPS para SSH s\u00f3 nos repos para os quais voc\u00ea tem chave.", "Pull via this machine's own SSH config; converts HTTPS to SSH only for repos you have a key for.", "Pull con el config SSH f\u00edsico de esta m\u00e1quina; convierte HTTPS a SSH solo en repos para los que tiene clave.")),
        list(fn = "git_push_with_local_id(branch, auto_ssh)", desc = L("O mesmo, para push.", "Same, for push.", "Lo mismo, para push."))
      )
    ),
    list(
      group = L("Stash", "Stashing", "Stash"),
      items = list(
        list(fn = "git_stash_save(message_text, include_untracked)", desc = L("Guarda altera\u00e7\u00f5es locais com uma mensagem; n\u00e3o faz nada se n\u00e3o houver o que guardar.", "Stash uncommitted local changes with a message; no-ops cleanly if there's nothing to stash.", "Guarda cambios locales con un mensaje; no hace nada si no hay qu\u00e9 guardar.")),
        list(fn = "git_stash_list()", desc = L("Imprime e retorna as entradas de stash.", "Prints and returns the current stash entries.", "Imprime y devuelve las entradas de stash.")),
        list(fn = "git_stash_pop(stash_ref)", desc = L("Restaura uma entrada de stash (padr\u00e3o: a mais recente).", "Restores a stash entry (default: the most recent).", "Restaura una entrada de stash (por defecto: la m\u00e1s reciente)."))
      )
    ),
    list(
      group = L("Destrutivo / recupera\u00e7\u00e3o (zona de perigo)", "Destructive / recovery (danger zone)", "Destructivo / recuperaci\u00f3n (zona de peligro)"),
      items = list(
        list(fn = "git_pull_force_remote(branch, confirm, stash_backup, auto_ssh)", desc = L("Reseta (hard) o branch local para igualar o origin, com stash dos arquivos locais antes.", "Hard-resets the local branch to match origin, stashing local changes first by default.", "Resetea (hard) la rama local para igualar origin, con stash de los cambios locales antes.")),
        list(fn = "git_push_force_remote(branch, confirm, use_lease, backup_tag, auto_ssh)", desc = L("Force-push do hist\u00f3rico local sobre o remoto, com detec\u00e7\u00e3o de diverg\u00eancia e tag de backup local.", "Force-pushes local history over the remote's, with divergence detection and a local backup tag.", "Force-push del historial local sobre el remoto, con detecci\u00f3n de divergencia y etiqueta de respaldo local."))
      )
    )
  )

  list(pkg = "gitssh", ui = ui, workflows = workflows, reference = reference)
}
